<article class="pub-card pub-provider" id="<?=e($service)?>"><div class="pub-card-top"><h3><?=e($definition['name'])?></h3><span class="pub-status"><?=!empty($metadata['owner_declared'])?($status==='connected'?'Owner-confirmed · assisted':'Owner declaration · confirm target'):e(publishing_state_label($status))?></span></div><p><?=e($definition['description'])?></p>
<?php if($connection):?><p class="pub-help">Saved destination: <?=e($connection['display_name']??'')?>. <?=!empty($metadata['owner_declared'])?'This is your declaration; no provider identity or membership has been verified.':'Provider identity was read during setup; delivery checks it again.'?></p><?php endif;?>
<form method="post" action="<?=url('/write/connections/'.$service.'/configure')?>"><?=csrf_field()?>
<?php if($service!=='signal'):?><div class="field"><label for="community-credential-<?=e($service)?>"><?=$service==='telegram'?'Bot token from BotFather':'Incoming Discord webhook URL'?></label><input type="password" autocomplete="new-password" id="community-credential-<?=e($service)?>" name="credential"><small>Stored encrypted. Setup performs read-only verification; it does not send a test message.</small></div><?php if($service==='telegram'):?><div class="field"><label for="telegram-target">Exact channel/supergroup @username or numeric -100… ID</label><input id="telegram-target" name="destination" autocomplete="off"><small>The bot must be an administrator with posting rights. This does not connect a personal inbox or import members.</small></div><?php endif;?><label class="pub-choice"><input type="checkbox" name="assisted_only" value="1"><span>Use an owner-declared assisted destination instead; do not verify or save a bot/webhook credential.</span></label><?php endif;?>
<div class="field"><label for="community-label-<?=e($service)?>">Private group/channel label for assisted delivery</label><input id="community-label-<?=e($service)?>" name="destination_label" maxlength="150" <?=$service==='signal'?'required':''?>><small>Enter the exact name you will check in the app. Do not paste group invitations or member details. Signal posts are completed in Signal, then recorded with a private receipt.</small></div><button class="wbtn" type="submit">Save & review destination</button></form>
<?php if($status==='pending_confirmation'&&$resources):?><form method="post" action="<?=url('/write/connections/'.$service.'/confirm')?>"><?=csrf_field()?><div class="field"><label for="community-resource-<?=e($service)?>">Destination to confirm</label><select required id="community-resource-<?=e($service)?>" name="resource"><?php foreach($resources as$item):?><option value="<?=e((string)$item['id'])?>"><?=e($item['name'])?></option><?php endforeach;?></select></div><label class="pub-choice"><input type="checkbox" name="confirm_identity" required><span>I checked this exact destination and its intended audience.</span></label><button class="wbtn primary" type="submit">Confirm destination</button></form><?php endif;?>
<?php if($connection&&$status!=='disconnected'):?><form method="post" action="<?=url('/write/connections/'.$service.'/disconnect')?>"><?=csrf_field()?><button class="pub-muted-button" type="submit">Remove saved connection</button></form><?php endif;?></article>
